 ['report-from','report-to'].forEach(id=>$('#'+id)?.addEventListener('change',e=>{const from=id==='report-from'?e.target.value:ui.reportFrom,to=id==='report-to'?e.target.value:ui.reportTo;if(!from||!to||from>to){notify('Rentang tanggal tidak valid.');e.target.value=id==='report-from'?ui.reportFrom:ui.reportTo;return;}ui.reportFrom=from;ui.reportTo=to;render();}));
