async function compressMemberPhoto(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Format foto belum didukung. Pilih JPG, PNG, atau WebP; ubah HEIC ke JPG terlebih dahulu.');
 if(file.size>15*1024*1024)throw new Error('Foto terlalu besar. Pilih foto di bawah 15 MB.');
 const url=URL.createObjectURL(file),img=new Image();
 try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('Foto tidak dapat dibaca. Coba file JPG atau PNG lain.'));img.src=url;});
  if(!img.naturalWidth||!img.naturalHeight)throw new Error('Ukuran foto tidak valid.');
  const scale=Math.min(1,480/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
  for(const quality of [.82,.68,.5,.35]){const result=canvas.toDataURL('image/jpeg',quality);if(result.length<=120000)return result;}
  throw new Error('Foto belum bisa diperkecil. Coba foto lain yang lebih sederhana.');
 }finally{URL.revokeObjectURL(url);}
}
