 <div class="note-box">${esc(byId('packages',m.packageId)?.name||'Belum memiliki paket gym')}${m.frozenUntil?` · Dibekukan sampai ${date(m.frozenUntil,true)}`:''}${reserved?` · ${reserved} kredit PT dicadangkan`:''}${m.notes?`<br>${esc(m.notes)}`:''}</div>
