function memberCard(id){
 const m=byId('members',id);if(!m)return;
 const settings=G.state.settings,payload=G.memberQrPayload(id);
 modal('Kartu member',`<article class="membership-card" aria-label="Kartu member ${esc(m.name)}"><header><div><span class="card-kicker">MEMBERSHIP CARD</span><h2>${esc(settings.gymName)}</h2><p>${esc(settings.branch)} · ${esc(settings.phone)}</p></div><span class="brand-mark"></span></header><div class="membership-card-body"><div class="membership-card-person">${memberAvatar(m)}<div><h3>${esc(m.name)}</h3><p>${esc(m.id)} · ${esc(customerTypes[G.getCustomerType(m)])}</p></div></div><div class="membership-card-qr">${window.MemberQR.svg(payload,240)}</div><div class="membership-card-dates"><div><span>TANGGAL MULAI</span><strong>${date(m.startDate)}</strong></div><div><span>TANGGAL EXPIRED</span><strong>${date(m.endDate)}</strong></div></div><div class="membership-card-address">${esc(settings.address)}</div></div><footer>${memberBadge(m)}<span>Status akses mengikuti data terbaru di resepsionis.</span></footer></article><div class="member-card-help note-box mt-16">Tunjukkan QR ini kepada resepsionis. Kode tetap sama saat diperpanjang; unduh ulang kartu untuk memperbarui tanggal cetaknya.<br>Demo: scan di browser resepsionis yang menyimpan data member ini. Data antarperangkat belum tersinkron.</div><div class="member-code-row"><label for="member-code">Kode untuk scanner / salin manual</label><input id="member-code" readonly value="${esc(payload)}"></div>`,`${button('Kembali ke profil','member-detail','','',`data-id="${esc(id)}"`)}${button('Salin kode','copy-member-code','','copy')}${button('Cetak / Simpan PDF','print-member-card','','print')}${button('Unduh kartu PNG','download-member-card','primary','download',`data-id="${esc(id)}"`)}`,true);
 document.body.classList.add('printing-member-card');
}
async function downloadMemberCard(id,el){
 const member=byId('members',id);if(!member)return;el.disabled=true;
 try{const blob=await window.MemberQR.cardPng({member,settings:G.state.settings,statusLabel:statuses[G.status(member)]?.[0]||'',payload:G.memberQrPayload(id)});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Kartu-member-${member.id.replace(/[^a-z0-9_-]/gi,'')}.png`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);notify('Kartu member PNG diunduh.');}finally{if(el.isConnected)el.disabled=false;}
}
function freezeForm(id){formModal('Bekukan membership',`<div class="note-box mb-16">Selama dibekukan, member tidak dapat check-in. Masa aktif diperpanjang sesuai hari pembekuan yang benar-benar digunakan.</div>${field('Jumlah hari','days','7','number','required min="1" max="90" step="1"')}`,'Bekukan membership',v=>{G.setFreeze(id,Number(v.days));saveAndClose('Membership dibekukan.');});}
function reminder(id){const m=byId('members',id),text=`Halo ${m.name}, salam dari ${G.state.settings.gymName}! Membership kamu ${G.daysLeft(m)<0?'sudah berakhir pada':'akan berakhir pada'} ${date(m.endDate)}. Yuk lanjutkan progres latihanmu. Hubungi resepsionis untuk perpanjangan paket. Sampai ketemu di gym!`;modal('Template pengingat',`<p class="subtitle mb-16">Tinjau teks di bawah, lalu salin untuk dikirim sendiri. Aplikasi tidak mengirim pesan.</p><label for="reminder-text">Pesan untuk ${esc(m.name)}</label><textarea id="reminder-text" rows="6">${esc(text)}</textarea>`,`${button('Tutup','close-modal')}${button('Salin teks','copy-reminder','primary','copy')}`);}
function checkoutModal(){if(!ui.cart.length)return;const shift=G.shiftSummary();if(!shift.shift)return openShiftForm();if(ui.cart.some(x=>x.type==='package')&&!ui.memberId)return notify('Pilih member sebelum menjual paket.');if(!Number.isInteger(ui.discount)||ui.discount<0||ui.discount>cartSubtotal())return notify('Diskon harus berupa rupiah bulat dan tidak melebihi subtotal.');ui.paymentMethod='cash';ui.paymentKey=crypto.randomUUID?.()||String(Date.now())+Math.random();paymentModal();}
function paymentModal(){const total=cartSubtotal()-ui.discount;modal('Review & pembayaran',`<div class="checkout-amount"><span>Total pembayaran</span><strong>${money(total)}</strong></div><div class="receipt-items mb-16">${ui.cart.map(x=>{const p=byId(x.type==='product'?'products':'packages',x.id);return `<div class="receipt-item"><span>${x.qty} × ${esc(p.name)}</span><strong>${money(x.qty*p.price)}</strong></div>`;}).join('')}<div class="receipt-item"><span>Diskon</span><strong>− ${money(ui.discount)}</strong></div></div><p class="field-hint mb-16">${ui.memberId?`Member: ${esc(byId('members',ui.memberId)?.name)}`:'Pelanggan umum'}</p><div class="method-options">${[['cash','cash'],['qris','qr'],['transfer','bank']].map(([method,glyph])=>`<button class="method-option ${ui.paymentMethod===method?'active':''}" data-action="payment-method" data-value="${method}">${icon(glyph,21)}${methods[method]}</button>`).join('')}</div><form id="payment-form">${ui.paymentMethod==='cash'?`${field('Uang diterima (Rp)','cashReceived',total,'number','required min="0" step="1"')}<div class="cart-totals"><div><span>Kembalian</span><strong id="change-preview">${money(0)}</strong></div></div>`:`<div class="note-box warning">${methods[ui.paymentMethod]} dicatat manual dalam mode demo. Aplikasi tidak membuat QR pembayaran dan tidak memverifikasi mutasi bank.</div><label class="checkbox-label"><input name="confirmed" type="checkbox" required> Saya sudah memeriksa bukti pembayaran ${methods[ui.paymentMethod]} untuk transaksi demo ini.</label>`}${field('Catatan (opsional)','notes','','text','maxlength="200"')}</form>`,`${button('Kembali','close-modal')}<button class="button primary" form="payment-form" type="submit">${icon('checkmark',14)} Catat pembayaran demo</button>`);
 $('#f-cashReceived')?.addEventListener('input',e=>{$('#change-preview').textContent=Number(e.target.value)>=total?money(Number(e.target.value)-total):'Kurang '+money(total-Number(e.target.value));});
 $('#payment-form').addEventListener('submit',e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));act(()=>{const tx=G.checkout({memberId:ui.memberId||null,items:ui.cart,discount:ui.discount,method:ui.paymentMethod,cashReceived:Number(values.cashReceived)||0,confirmed:values.confirmed==='on',notes:values.notes,idempotencyKey:ui.paymentKey});ui.cart=[];ui.discount=0;render();receipt(tx.id);notify('Pembayaran dicatat. Struk siap.');});});}
function receipt(id){const t=byId('transactions',id);if(!t)return;const settings=G.state.settings;modal('Detail transaksi',`<div class="receipt"><div class="receipt-icon">${icon(validTx(t)?'checkmark':'close',24)}</div><h2>${validTx(t)?'Pembayaran tercatat':'Transaksi dibatalkan'}</h2><p class="receipt-id">${esc(t.number||t.id)} · STRUK DEMO</p><div class="receipt-meta"><div><span>Gym / cabang</span><strong>${esc(settings.gymName)} · ${esc(settings.branch)}</strong></div><div><span>Tanggal</span><strong>${date(txDate(t))}</strong></div><div><span>Member</span><strong>${esc(t.memberName||'Pelanggan umum')}</strong></div><div><span>Metode pembayaran</span><strong>${methods[t.method]}</strong></div></div><div class="receipt-items">${txItems(t).map(x=>`<div class="receipt-item"><span>${x.qty} × ${esc(x.name)}</span><strong>${money(x.total)}</strong></div>`).join('')}<div class="receipt-item"><span>Subtotal</span><strong>${money(t.subtotal)}</strong></div><div class="receipt-item"><span>Diskon</span><strong>− ${money(t.discount)}</strong></div></div><div class="receipt-total"><span>Total</span><span>${money(t.total)}</span></div>${t.method==='cash'?`<div class="receipt-item"><span>Uang diterima</span><span>${money(t.cashReceived)}</span></div><div class="receipt-item"><span>Kembalian</span><span>${money(t.change)}</span></div>`:''}<p class="receipt-note">${esc(settings.address)}<br>${esc(settings.phone)}<br>Terima kasih. Sampai jumpa di latihan berikutnya.</p>${!validTx(t)?`<div class="note-box danger mt-16">Alasan pembatalan: ${esc(t.voidReason||t.reason||'Tercatat dalam audit')}</div>`:''}</div>`,`${validTx(t)?button('Batalkan transaksi','void-tx','danger','','data-id="'+esc(id)+'"'):''}${button('Cetak struk','print','','print')}${button('Selesai','close-modal','primary')}`);}
function bookPT(){const s=G.state,options=s.members.filter(m=>m.ptCredits>0).map(m=>[m.id,`${m.name} · ${m.ptCredits} kredit`]);formModal('Jadwalkan personal training',`<div class="form-grid">${selectField('Member','memberId',[['','Pilih member'],...options],'','required')}${selectField('Trainer','trainerId',[['','Pilih trainer'],...s.staff.filter(x=>x.role==='trainer'&&x.active).map(x=>[x.id,x.name])],'','required')}${field('Tanggal','date',ui.ptDate,'date',`required min="${day()}"`)}${field('Mulai (WIB)','time','16:00','time','required')}${textField('Catatan latihan (opsional)','notes','','maxlength="300"')}</div><div class="note-box mt-16">Satu sesi berlangsung 60 menit. Kredit yang sudah dipesan untuk sesi lain tidak dapat dipakai kembali.</div>`,'Simpan jadwal',v=>{G.bookPT(v);ui.ptDate=v.date;saveAndClose('Sesi PT berhasil dijadwalkan.');});}
function productForm(id){const p=id?byId('products',id):{name:'',sku:'',category:'Minuman',price:0,cost:0,stock:0,minStock:5,active:true};formModal(id?'Edit produk':'Tambah produk',`<div class="form-grid">${field('Nama produk','name',p.name,'text','required maxlength="100"')}${field('SKU','sku',p.sku,'text','required maxlength="40"')}${field('Kategori','category',p.category,'text','required maxlength="50"')}${field('Harga jual (Rp)','price',p.price,'number','required min="0" step="1"')}${field('Harga modal (Rp)','cost',p.cost,'number','required min="0" step="1"')}${field('Stok minimum','minStock',p.minStock,'number','required min="0" step="1"')}${!id?field('Stok awal','stock',p.stock,'number','required min="0" step="1"'):''}${selectField('Status','active',[['true','Aktif'],['false','Nonaktif']],String(p.active))}</div>${id?`<p class="field-hint mt-16">Stok saat ini ${p.stock} unit. Gunakan “Terima stok” untuk mencatat penambahan barang beserta pembeliannya.</p>`:''}`,'Simpan produk',v=>{G.saveEntity('products',{...p,...v,price:Number(v.price),cost:Number(v.cost),minStock:Number(v.minStock),stock:id?p.stock:Number(v.stock),active:v.active==='true'});saveAndClose('Produk disimpan.');});}
function receiveStock(id){const p=byId('products',id),sup=G.state.suppliers;formModal('Terima stok · '+p.name,`<div class="form-grid">${selectField('Pemasok','supplierId',[['','Pilih pemasok'],...sup.map(x=>[x.id,x.name])],'','required')}${field('Jumlah barang','qty',1,'number','required min="1" step="1"')}${field('Harga modal per unit (Rp)','unitCost',p.cost,'number','required min="0" step="1"')}${selectField('Metode pembayaran','method',Object.entries(methods),'transfer')}</div><div class="note-box mt-16">Stok bertambah setelah disimpan. Total pembelian masuk laporan arus kas; pembayaran tunai mengurangi kas shift.</div>`,'Terima & catat pembelian',v=>{G.receiveStock({...v,productId:id,qty:Number(v.qty),unitCost:Number(v.unitCost)});saveAndClose('Stok bertambah dan pembelian dicatat.');});}
function expenseForm(){formModal('Catat pengeluaran operasional',`<div class="form-grid">${selectField('Kategori','category',['Listrik & air','Kebersihan','Perawatan alat','Gaji & komisi','Sewa','Pemasaran','Lainnya'].map(x=>[x,x]))}${field('Nominal (Rp)','amount','','number','required min="1" step="1"')}${selectField('Metode pembayaran','method',Object.entries(methods),'cash')}${textField('Keperluan','description','','required maxlength="300"')}</div>`,'Catat pengeluaran',v=>{G.addExpense({...v,amount:Number(v.amount)});saveAndClose('Pengeluaran dicatat.');});}
function openShiftForm(){formModal('Buka shift kasir',`${field('Kas awal di laci (Rp)','openingCash',300000,'number','required min="0" step="1"')}<p class="field-hint mt-16">Masukkan jumlah uang tunai awal yang sudah dihitung. Saldo awal tidak dihitung sebagai pendapatan.</p>`,'Buka shift',v=>{G.openShift(Number(v.openingCash));saveAndClose('Shift kasir dibuka.');});}
function closeShiftForm(){const s=G.shiftSummary();formModal('Hitung & tutup shift',`<div class="checkout-amount"><span>Kas seharusnya</span><strong>${money(s.expectedCash)}</strong></div>${field('Kas aktual di laci (Rp)','closingCash','','number','required min="0" step="1"')}<div class="cart-totals"><div><span>Selisih kas</span><strong id="variance-preview">Isi jumlah kas aktual</strong></div></div>${textField('Catatan selisih (jika ada)','notes','','maxlength="300"')}<div class="note-box mt-16">Penjualan QRIS dan transfer tidak termasuk uang di laci. Setelah shift ditutup, transaksi pada shift ini tidak dapat dibatalkan.</div>`,'Tutup shift',v=>{const closed=G.closeShift({closingCash:Number(v.closingCash),notes:v.notes});saveAndClose('Shift ditutup. Selisih kas: '+money(closed.variance));});$('#f-closingCash').addEventListener('input',e=>$('#variance-preview').textContent=money(Number(e.target.value)-s.expectedCash));}
function masterForm(type,id){const x=id?byId(type,id):{},defaults={packages:{name:'',kind:'membership',price:350000,days:30,sessions:0,description:'',active:true},suppliers:{name:'',phone:''},staff:{name:'',role:'cashier',phone:'',active:true},announcements:{title:'',body:''}},v={...defaults[type],...x};let body='';if(type==='packages')body=`${field('Nama paket','name',v.name,'text','required maxlength="100"')}${selectField('Jenis paket','kind',[['membership','Membership'],['pt','Personal training'],['daypass','Day pass']],v.kind)}${field('Harga (Rp)','price',v.price,'number','required min="0" step="1"')}${field('Durasi akses (hari)','days',v.days,'number','required min="0" step="1"')}${field('Jumlah sesi PT','sessions',v.sessions,'number','required min="0" step="1"')}${selectField('Status','active',[['true','Aktif'],['false','Nonaktif']],String(v.active))}${textField('Deskripsi','description',v.description,'maxlength="300"')}<p class="field-hint full">Membership: isi durasi hari, sesi 0. PT: durasi 0, isi jumlah sesi. Day pass: durasi 1 hari, sesi 0.</p>`;if(type==='suppliers')body=`${field('Nama pemasok','name',v.name,'text','required maxlength="100"')}${field('Nomor telepon','phone',v.phone,'tel','maxlength="25"')}`;if(type==='staff')body=`${field('Nama staf','name',v.name,'text','required maxlength="100"')}${selectField('Peran','role',[['cashier','Kasir'],['trainer','Trainer'],['manager','Manajer'],['owner','Owner']],v.role)}${field('Nomor telepon','phone',v.phone,'tel','maxlength="25"')}${selectField('Status','active',[['true','Aktif'],['false','Nonaktif']],String(v.active))}`;if(type==='announcements')body=`${field('Judul','title',v.title,'text','required maxlength="100"')}${textField('Isi pengumuman','body',v.body,'required maxlength="1000"')}`;formModal((id?'Edit ':'Tambah ')+({packages:'paket gym',suppliers:'pemasok',staff:'staf',announcements:'pengumuman'})[type],`<div class="form-grid">${body}</div>`,'Simpan',values=>{const record={...v,...values};if(type==='packages'){['price','days','sessions'].forEach(k=>record[k]=Number(record[k]));record.active=values.active==='true';}if(type==='staff')record.active=values.active==='true';G.saveEntity(type,record);saveAndClose('Data master disimpan.');});}
function download(content,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const quote=v=>{let s=String(v??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download('\ufeff'+ui.reportRows.map(row=>row.map(quote).join(',')).join('\r\n'),`FORMA-${ui.report}-${ui.reportFrom}-${ui.reportTo}.csv`,'text/csv;charset=utf-8');notify('CSV sesuai tampilan diunduh.');}
function importBackup(){formModal('Impor backup data',`<div class="note-box warning mb-16">Backup yang valid akan mengganti seluruh data pada browser ini. Ekspor data sekarang jika masih diperlukan.</div><label for="backup-file">File backup JSON</label><input id="backup-file" type="file" accept="application/json,.json" required><label class="checkbox-label"><input type="checkbox" required>Saya memahami data saat ini akan diganti.</label>`,'Validasi & impor',async()=>{const file=$('#backup-file').files[0];if(!file)return;try{if(file.size>20*1024*1024)throw new Error('Backup terlalu besar. Maksimal 20 MB.');const content=await file.text();G.importBackup(content);ui.cart=[];ui.memberId='';ui.discount=0;saveAndClose('Backup valid. Data berhasil dipulihkan.');}catch(error){$('.form-error').textContent=error.message;$('.form-error').classList.add('visible');}});}
function alerts(){const s=G.state,soon=s.members.filter(m=>m.endDate&&['active','expiring'].includes(G.status(m))&&G.daysLeft(m)>=0&&G.daysLeft(m)<=7),low=s.products.filter(p=>p.stock<=p.minStock);modal('Pengingat operasional',`<div class="feedback-list"><div><strong>${soon.length} member segera berakhir</strong><p>Siapkan percakapan perpanjangan untuk tujuh hari ke depan.</p><div class="mt-16">${button('Lihat member','go','sm','','data-route="members"')}</div></div><div><strong>${low.length} produk perlu restock</strong><p>Stok sudah mencapai batas minimum.</p><div class="mt-16">${button('Buka produk & stok','go','sm','','data-route="products"')}</div></div>${s.announcements.map(a=>`<div><strong>${esc(a.title)}</strong>${esc(a.body)}</div>`).join('')}</div>`,button('Tutup','close-modal'));}
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id,value=el.dataset.value;
 if(a==='close-modal')return closeModal();if(a==='menu'){ui.mobile=!ui.mobile;return render();}if(a==='go'){closeModal();return navigate(el.dataset.route);}if(a==='new-sale')return navigate('pos');if(a==='alerts')return alerts();
 if(a==='tab'){ui[el.dataset.kind]=value;ui.query='';return render();}if(a==='chart-period'){ui.chartPeriod=value;return render();}if(a==='dash-period'){ui.dashPeriod=value;return render();}if(a==='expiry-filter'){ui.expiry=value;return render();}
 if(a==='add-cart')return addCart(id,el.dataset.type);if(a==='cart-remove'){ui.cart.splice(Number(el.dataset.index),1);return render();}if(a==='cart-qty'){const x=ui.cart[Number(el.dataset.index)],delta=Number(el.dataset.delta),p=byId(x.type==='product'?'products':'packages',x.id);if(delta>0&&x.type==='package'&&p.kind!=='pt')return notify('Paket akses gym dibatasi satu per transaksi.');if(delta>0&&x.type==='product'&&x.qty>=p.stock)return notify('Stok tidak mencukupi.');x.qty+=delta;if(x.qty<=0)ui.cart.splice(Number(el.dataset.index),1);return render();}
 if(a==='checkout')return checkoutModal();if(a==='payment-method'){ui.paymentMethod=value;return paymentModal();}if(a==='receipt')return receipt(id);if(a==='print')return window.print();
 if(a==='member-card')return memberCard(id);if(a==='download-member-card')return downloadMemberCard(id,el);if(a==='print-member-card')return window.print();if(a==='scan-camera')return scanCamera();
 if(a==='copy-member-code'){const input=$('#member-code');try{await navigator.clipboard.writeText(input.value);notify('Kode member disalin.');}catch{input.focus();input.select();notify('Kode dipilih. Gunakan Salin pada perangkat.');}return;}
 if(a==='add-member')return memberForm();if(a==='edit-member')return memberForm(id);if(a==='member-detail')return memberDetail(id);if(a==='renew'){ui.memberId=id;ui.catalog='membership';closeModal();return navigate('pos');}if(a==='freeze')return freezeForm(id);if(a==='unfreeze'){G.unfreeze(id);saveAndClose('Membership diaktifkan kembali.');return memberDetail(id);}if(a==='remind')return reminder(id);
 if(a==='copy-reminder'){try{await navigator.clipboard.writeText($('#reminder-text').value);notify('Teks pengingat disalin.');}catch{const t=$('#reminder-text');t.focus();t.select();notify('Teks dipilih. Gunakan Salin pada perangkat.');}return;}
 if(a==='check-in')return scanMemberCode(id);if(a==='pt-today'){ui.ptDate=day();return render();}if(a==='book-pt')return bookPT();if(a==='complete-pt'){return formModal('Selesaikan sesi PT','<p class="subtitle">Konfirmasi bahwa sesi ini sudah dilaksanakan. Satu kredit PT akan dipotong.</p>','Selesaikan sesi',()=>{G.completePT(id);saveAndClose('Sesi PT selesai. Satu kredit dipotong.');});}if(a==='cancel-pt'){return formModal('Batalkan sesi PT','<p class="subtitle">Sesi dibatalkan dan reservasi kredit dilepaskan. Kredit member tidak dipotong.</p>','Batalkan sesi',()=>{G.cancelPT(id);saveAndClose('Jadwal PT dibatalkan.');});}
 if(a==='edit-product')return productForm(id);if(a==='receive-stock')return receiveStock(id);if(a==='purchase-history'){ui.report='purchases';return navigate('reports');}if(a==='add-expense')return expenseForm();if(a==='open-shift')return openShiftForm();if(a==='close-shift')return closeShiftForm();
 if(a==='report-period'){ui.reportFrom=value==='today'?day():monthStart();ui.reportTo=day();return render();}if(a==='export-csv')return exportCSV();if(a==='void-tx'){return formModal('Batalkan seluruh transaksi',`<div class="note-box warning mb-16">Seluruh transaksi dibatalkan. Stok, pendapatan, dan benefit yang belum digunakan dikembalikan. Catatan asli tetap ada. Hanya transaksi shift berjalan yang dapat dibatalkan.</div>${textField('Alasan pembatalan','reason','','required minlength="5" maxlength="300"')}`,'Konfirmasi pembatalan',v=>{G.voidTransaction(id,v.reason);saveAndClose('Transaksi dibatalkan dan laporan diperbarui.');receipt(id);});}
 if(a==='edit-master')return masterForm(el.dataset.type,id);if(a==='export-backup'){download(G.exportBackup(),`FORMA-backup-${day()}.json`,'application/json');return notify('Backup JSON diunduh.');}if(a==='import-backup')return importBackup();if(a==='reset-demo'){return formModal('Reset data demo',`<div class="note-box danger mb-16">Semua transaksi dan perubahan di browser ini akan diganti dengan data fiktif awal. Simpan backup sebelum melanjutkan.</div>${field('Ketik RESET untuk melanjutkan','confirm','','text','required pattern="RESET" autocomplete="off"')}`,'Reset data demo',v=>{if(v.confirm!=='RESET')throw new Error('Ketik RESET dengan huruf besar.');G.resetDemo();ui.cart=[];ui.memberId='';ui.discount=0;saveAndClose('Data demo berhasil direset.');});}
}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;Promise.resolve().then(()=>handleAction(target)).catch(error=>{const message=$('.form-error');if(message){message.textContent=error.message;message.classList.add('visible');}else notify(error.message);});});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopCamera();if($('#member-camera'))closeModal();}});
window.addEventListener('pagehide',stopCamera);
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const all=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]',$('.modal')),first=all[0],last=all[all.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{closeModal();ui.route=location.hash.slice(1)||'dashboard';ui.mobile=false;ui.query='';render();window.scrollTo(0,0);});
render();
